// === Tab: mySketch ===
// Chromakinetica
// For the WCCChallenge << Gravity >>. Join the discord! https://discord.gg/S8c7qcjw2b
//
// The theme "gravity" begs for including some physics. For this week's sketch,
// a simple physics engine where pairs of balls connected by a line that leaves
// a gradient trail, bouncing off the walls and pegs. The result is a colorful
// and chaotic composition


let Engine = Matter.Engine,
  Render = Matter.Render,
  World = Matter.World,
  Bodies = Matter.Bodies
let engine, world
let pegs = [],
  ballPairs = []
let ballSize = 20,
  pegSize = 20,
  pegSeparation = 120 ,
  maxBallPairs = 4
let opacityRange = [30, 60]
let grainBuffer, grainShader, mainCanvas, grainSeed
let cw, ch
let marginX, marginY
let buffer
let showShapes = true

function setup() {
  cw = windowWidth
  ch = windowHeight
  mainCanvas = createCanvas(cw, ch)

  grainBuffer = createGraphics(width, height, WEBGL)
  grainShader = grainBuffer.createShader(vert, frag)
  grainSeed = random()

  marginX = min(cw / 10, 100)
  marginY = min(ch / 10, 100)

  buffer = createGraphics(cw, ch)
  buffer.strokeCap(SQUARE)

  colorMode(HSB, 360, 100, 100, 100)

  engine = Engine.create()
  world = engine.world
  Matter.Runner.run(engine)

  let pds = new FastPoissonDiskSampling({
    shape: [cw, ch],
    radius: pegSeparation,
    tries: 30,
  })

  let points = pds.fill()
  for (let point of points) {
    let x = point[0]
    let y = point[1]
    let peg = Bodies.circle(x, y, pegSize, { isStatic: true, restitution: 1.2 })
    pegs.push(peg)
    World.add(world, peg)
  }

  // Create walls
  let wallOptions = { isStatic: true, restitution: 1 }
  let wallThickness = 20
  World.add(world, [
    Bodies.rectangle(0, ch / 2, wallThickness, ch, wallOptions),
    Bodies.rectangle(cw, ch / 2, wallThickness, ch, wallOptions),
  ])

	maxBallPairs = max(floor(cw / 400), 4)
  spawnBalls()
}

function spawnBalls(force = false) {
  if (ballPairs.length >= maxBallPairs && !force) {
    return
  }
  if (force) {
    for (let balls of ballPairs) {
      World.remove(world, balls)
    }
    ballPairs = []
  }
  let ballOptions = { restitution: 1.1 }
  let x1 = random(0, cw / 2)
  let x2 = random(cw / 2, cw)
  if (abs(x1 - x2) > cw / 3) {
    if (random() < 0.5) {
      x2 = x1 + cw / 3
    } else {
      x1 = x2 - cw / 3
    }
  }
  let ballA = Bodies.circle(x1, -marginY, ballSize, ballOptions)
  let ballB = Bodies.circle(x2, -marginY, ballSize, ballOptions)
  let colors = getRandomColorPair()
  ballA.color = colors[0]
  ballB.color = colors[1]
  ballA.sw = random(0.5, 4)
  ballB.sw = ballA.sw
  ballA.staleCount = 0
  ballB.staleCount = 0
  ballA.previousPosition = ballA.position
  ballB.previousPosition = ballB.position

  let balls = [ballA, ballB]
  ballPairs.push(balls)
  World.add(world, balls)
}

function draw() {
  background(255)
  // Draw the buffer but leave out the margin, only draw the center
  image(
    buffer, marginX, marginY, cw - 2 * marginX, ch - 2 * marginY,
    marginX, marginY, cw - 2 * marginX, ch - 2 * marginY
  )

  if ((frameCount % 2) * 60 === 0) {
    spawnBalls()
  }

  // Draw border around painted area
  stroke(0, 0, 0, 60)
  strokeWeight(20)
  noFill()
  rect(marginX, marginY, cw - 2 * marginX, ch - 2 * marginY)
  if (showShapes) {
    // Draw pegs
    for (let peg of pegs) {
      fill(0, 0, 100, 15)
      stroke(0, 0, 100, 50)
      strokeWeight(5)
      ellipse(peg.position.x + 2, peg.position.y + 2, pegSize * 1.5)
      noFill()
      strokeWeight(3)
      stroke(0, 0, 20, 100)
      ellipse(peg.position.x, peg.position.y, pegSize * 1.5)
    }
    // Draw balls and lines
    for (let balls of ballPairs) {
      for (let ball of balls) {
        stroke(0)
        strokeWeight(3)
        fill(ball.color)
        circle(ball.position.x, ball.position.y, ballSize * 2)
      }
    }
  }

  // Draw line between balls
  for (let balls of ballPairs) {
    buffer.noStroke()

    let gradient = buffer.drawingContext.createLinearGradient(
      balls[0].position.x,
      balls[0].position.y,
      balls[1].position.x,
      balls[1].position.y
    )
    gradient.addColorStop(0, balls[0].color)
    gradient.addColorStop(1, balls[1].color)
    buffer.drawingContext.fillStyle = gradient
    buffer.quad(
      balls[0].previousPosition.x,
      balls[0].previousPosition.y,
      balls[1].previousPosition.x,
      balls[1].previousPosition.y,
      balls[1].position.x,
      balls[1].position.y,
      balls[0].position.x,
      balls[0].position.y
    )
    let deltaMovement = 1,
      maxStaleFrames = 30
    for (let ball of balls) {
      // Check if ball has not moved, if so, shake it
      if (
        abs(ball.position.x - ball.previousPosition.x) < deltaMovement &&
        abs(ball.position.y - ball.previousPosition.y) < deltaMovement
      ) {
        ball.staleCount += 1
      } else {
        ball.staleCount = 0
      }
      if (ball.staleCount >= maxStaleFrames) {
        shakeBall(ball, 0.01)
      }
      ball.previousPosition = { x: ball.position.x, y: ball.position.y } // Save copy of position
    }
  }

  // Check if balls are off screen
  for (let balls of ballPairs) {
    if (balls[0].position.y > height && balls[1].position.y > height) {
      World.remove(world, balls)
      ballPairs.splice(ballPairs.indexOf(balls), 1)
      spawnBalls()
    }
  }

  if (frameCount % 5 === 0) {
    grainSeed = noise(frameCount / 30)
  }
  applyGrain()
}

function getRandomColorPair() {
	let hueDistance = 100
  let color1 = [random(360), random(50, 100), random(50, 100), random(...opacityRange)]
  let color2 = [(color1[0] + random(hueDistance, 360 - hueDistance)) % 360, random(50, 100), random(50, 100), random(...opacityRange)]
  return [color(color1), color(color2)]
}

function mousePressed() {
  for (let balls of ballPairs) {
    for (let ball of balls) {
      shakeBall(ball, 0.01)
    }
  }
}

function shakeBall(ball, forceMagnitude = 0.05) {
  let force = p5.Vector.random2D().mult(forceMagnitude)
  Matter.Body.applyForce(ball, ball.position, force)
}

function keyPressed() {
  if (key === "s" || key === "S") {
    for (let balls of ballPairs) {
      for (let ball of balls) {
        shakeBall(ball, 0.01)
      }
    }
  }
  if (key === "d" || key === "D") {
    showShapes = !showShapes
  }
  if (key === "r" || key === "R") {
    spawnBalls(true)
  }
  if (key === "c" || key === "C") {
    resetImage()
  }
  if (key === "e" || key === "E") {
    saveCanvas("chrommakinetica", "png")
  }
}

function resetImage () {
  buffer.clear()
  buffer.background(255)
}

const vert = `
precision highp float;
attribute vec3 aPosition;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying vec2 vVertTexCoord;

void main(void) {
  vec4 positionVec4 = vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * uModelViewMatrix * positionVec4;
  vVertTexCoord = aTexCoord;
}
`

const frag = `
precision highp float;
varying vec2 vVertTexCoord;

uniform sampler2D source;
uniform float noiseSeed;
uniform float noiseAmount;

// Noise functions
// https://gist.github.com/patriciogonzalezvivo/670c22f3966e662d2f83
float rand(vec2 n) {
  return fract(sin(dot(n, vec2(12.9898, 4.1414))) * 43758.5453);
}

void main() {
  // GorillaSun's grain algorithm
  vec4 inColor = texture2D(source, vVertTexCoord);
  gl_FragColor = clamp(inColor + vec4(
    mix(-noiseAmount, noiseAmount, fract(noiseSeed + rand(vVertTexCoord * 1234.5678))),
    mix(-noiseAmount, noiseAmount, fract(noiseSeed + rand(vVertTexCoord * 876.54321))),
    mix(-noiseAmount, noiseAmount, fract(noiseSeed + rand(vVertTexCoord * 3214.5678))),
    0.
  ), 0., 1.);
}
`

function applyGrain() {
  grainBuffer.clear()
  grainBuffer.reset()
  grainBuffer.push()
  grainBuffer.shader(grainShader)
  grainShader.setUniform("noiseSeed", grainSeed)
  grainShader.setUniform("source", mainCanvas)
  grainShader.setUniform("noiseAmount", 0.05)
  grainBuffer.rectMode(CENTER)
  grainBuffer.noStroke()
  grainBuffer.rect(0, 0, cw, ch)
  grainBuffer.pop()

  image(grainBuffer, 0, 0)
}

